    Bug 1987859 - Make DiscardOfflineMsg() callers responsible for "mail.discard_offline_msg_on_failure" pref check. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D264892

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index 05b2f0f936d..dae7abba951 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -94,8 +94,6 @@ static PRTime gtimeOfLastPurgeCheck;  // variable to know when to check for
 #define PREF_MAIL_PURGE_THRESHOLD_MB "mail.purge_threshold_mb"
 #define PREF_MAIL_PURGE_ASK "mail.purge.ask"
 #define PREF_MAIL_WARN_FILTER_CHANGED "mail.warn_filter_changed"
-#define PREF_MAIL_DISCARD_OFFLINE_ON_FAILURE \
-  "mail.discard_offline_msg_on_failure"

 const char* kUseServerRetentionProp = "useServerRetention";

@@ -1081,10 +1079,6 @@ NS_IMETHODIMP nsMsgDBFolder::HasMsgOffline(nsMsgKey msgKey, bool* result) {
 }

 NS_IMETHODIMP nsMsgDBFolder::DiscardOfflineMsg(nsMsgKey msgKey) {
-  if (!Preferences::GetBool(PREF_MAIL_DISCARD_OFFLINE_ON_FAILURE, true)) {
-    return NS_OK;
-  }
-
   GetDatabase();
   if (!mDatabase) return NS_ERROR_FAILURE;

diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index a5f59e3fffb..8a16deebdfc 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -9039,7 +9039,8 @@ class ImapOfflineMsgStreamListener : public nsIStreamListener {
     mListener = nullptr;
     mChannel->Close();
     mChannel = nullptr;
-    if (NS_FAILED(status)) {
+    if (NS_FAILED(status) &&
+        Preferences::GetBool("mail.discard_offline_msg_on_failure", true)) {
       // The streaming failed, discard the offline copy of the message.
       mFolder->DiscardOfflineMsg(mMsgKey);
     }
diff --git a/mailnews/protocols/common/src/OfflineStorage.cpp b/mailnews/protocols/common/src/OfflineStorage.cpp
index 78ac2c51fbe..db6961b56d1 100644
--- a/mailnews/protocols/common/src/OfflineStorage.cpp
+++ b/mailnews/protocols/common/src/OfflineStorage.cpp
@@ -40,7 +40,8 @@ NS_IMETHODIMP OfflineMessageReadListener::OnStartRequest(nsIRequest* request) {
 NS_IMETHODIMP OfflineMessageReadListener::OnStopRequest(nsIRequest* request,
                                                         nsresult status) {
   nsresult rv = mDestination->OnStopRequest(mChannel, status);
-  if (NS_FAILED(status)) {
+  if (NS_FAILED(status) &&
+      Preferences::GetBool("mail.discard_offline_msg_on_failure", true)) {
     // The streaming failed, discard the offline copy of the message so it can
     // be downloaded again later.
     mFolder->DiscardOfflineMsg(mMsgKey);
